def solve(s: str) -> bool:
    sys.setrecursionlimit(max(1000, 4 * len(s) + 100))
    close_to_open = {')': '(', ']': '[', '}': '{'}

    def walk(idx, opened):
        if idx == len(s):
            return not opened
        ch = s[idx]
        if ch in '([{':
            opened.append(ch)
            ok = walk(idx + 1, opened)
            opened.pop()
            return ok
        if ch in close_to_open:
            if not opened or opened[-1] != close_to_open[ch]:
                return False
            return walk(idx + 1, opened[:-1])
        return walk(idx + 1, opened)

    return walk(0, [])

