def solve(nested):
    """Return a flat list containing the leaves of a nested list, in order.

    Only lists are considered nestable containers; every other value
    (numbers, strings, tuples, None, ...) is a leaf. Implemented with an
    explicit stack so arbitrarily deep nesting is handled without hitting
    the recursion limit.
    """
    out = []
    stack = [iter(nested)]
    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if isinstance(item, list):
            stack.append(iter(item))
        else:
            out.append(item)
    return out

