def solve(matrix):
    """Return the determinant of a square integer matrix."""
    n = len(matrix)
    if n == 0:
        return 1
    if n == 1:
        return matrix[0][0]
    m = [list(row) for row in matrix]
    det = 1
    for col in range(n):
        pivot = None
        for r in range(col, n):
            if m[r][col] != 0:
                pivot = r
                break
        if pivot is None:
            return 0
        if pivot != col:
            m[col], m[pivot] = m[pivot], m[col]
            det = -det
        pv = m[col][col]
        det *= pv
        for r in range(col + 1, n):
            factor = m[r][col]
            for c in range(col, n):
                m[r][c] = m[r][c] * pv - factor * m[col][c]
            # divide the row by the previous pivot to stay in integers
            if col > 0:
                g = m[col - 1][col - 1] if m[col - 1][col - 1] else 1
                for c in range(col, n):
                    m[r][c] //= g
    return det

